INSERT INTO fuentes(id,nombre,url,uso) VALUES ('POWER','NASA POWER','https://power.larc.nasa.gov/','Histórico mensual'),('GPM','NASA GPM','https://gpm.nasa.gov/data','Precipitación satelital'),('SMAP','NASA SMAP','https://www.earthdata.nasa.gov/data/platforms/space-based-platforms/smap','Humedad del suelo'),('LANDSAT','Landsat','https://earthexplorer.usgs.gov/','Vegetación'),('METEO','Open-Meteo','https://open-meteo.com/','Estado actual y pronóstico'),('INEGI','INEGI','https://www.inegi.org.mx/servicios/catalogounico.html','Límites estatales y municipales') ON DUPLICATE KEY UPDATE url=VALUES(url);
